// The page's forward kinematics over the structure's `kinematics` block: `__fixtures__/hinge` is a
// served document as `cadgen serve` answers it for a two-part revolute hinge (a base, and an
// arm on joint `elbow` through (40, 0, 20) along +Y, range -10..120, connected at 30, with
// configurations `raised` (90) and `flat` (0)). It is regenerated by building that model (the
// engine's kinematics test, `HINGE`) and saving `GET /api/doc/<id>` and each part.
// `__fixtures__/finger` is the engine's index finger with one coupling, `index_curl` (its three
// knuckles 90, 100 and 70 degrees from straight): its structure, and the engine's own instance
// matrices posed at `{"index_curl": 0.6}` (`mechanism.posed_structure`), from building the engine's
// coupling test's `FINGER`.
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import * as THREE from "three";

import { createXbfScene } from "./xbfScene.js";
import {
  xbfCouplingControls, xbfCouplingValues, xbfCouplingWrite, xbfKinematics, xbfLinkPlacements, xbfPoseControls,
  xbfPosedMatrices, xbfPoseValues, xbfUnposable
} from "./xbfKinematics.js";
import { readXbmPart, xbmUnmeshedFaces } from "./xbm.js";

const FIXTURES = path.join(path.dirname(fileURLToPath(import.meta.url)), "__fixtures__");
const FIXTURE = path.join(FIXTURES, "hinge");
const STRUCTURE = JSON.parse(fs.readFileSync(path.join(FIXTURE, "structure.json"), "utf8"));
const FINGER = JSON.parse(fs.readFileSync(path.join(FIXTURES, "finger", "structure.json"), "utf8"));
const FINGER_POSED = JSON.parse(fs.readFileSync(path.join(FIXTURES, "finger", "posed.json"), "utf8"));
const ARM = 1;

/** The arm's corner (120, 10, 10) of its own frame at elbow `q`, in closed form (the engine's test's). */
function armTip(q) {
  const s = Math.sin(q * Math.PI / 180), c = Math.cos(q * Math.PI / 180);
  return [40 + 120 * s + 10 * c, 10, 20 + 120 * c - 10 * s];
}

const place = (m, p) => [0, 1, 2].map(row => m[row] * p[0] + m[4 + row] * p[1] + m[8 + row] * p[2] + m[12 + row]);
const near = (actual, expected, what) => actual.forEach((value, at) => assert.ok(Math.abs(value - expected[at]) < 1e-9, `${what}: ${actual} != ${expected}`));

test("forward kinematics from the block places the arm where the closed form says", () => {
  const kinematics = xbfKinematics(STRUCTURE);
  assert.equal(kinematics.pairs[0].type, "revolute");
  assert.deepEqual(kinematics.links.map(link => link.instances), [[0], [1]]);
  // As built, the structure's own matrices.
  const asBuilt = xbfPoseValues(kinematics);
  assert.deepEqual(asBuilt, { elbow: [30] });
  near(place(xbfPosedMatrices(STRUCTURE, asBuilt)[ARM], [120, 10, 10]), armTip(30), "as built");
  for (const [pose, q] of [["raised", 90], ["flat", 0], [{ elbow: -10 }, -10], [{ elbow: 75 }, 75]]) {
    const matrices = xbfPosedMatrices(STRUCTURE, xbfPoseValues(kinematics, pose));
    near(place(matrices[ARM], [120, 10, 10]), armTip(q), JSON.stringify(pose));
    assert.deepEqual(matrices[0], STRUCTURE.instances[0].matrix, "the ground stays");
  }
  // The links' placements compose: the ground where it is, the arm's frame on it.
  const [ground, arm] = xbfLinkPlacements(kinematics, { elbow: [30] });
  assert.deepEqual(ground, kinematics.links[0].matrix);
  near(arm, kinematics.links[1].matrix, "the arm's frame as built");
});

test("a pose naming a joint wrong, or a value out of range, is refused by name", () => {
  const kinematics = xbfKinematics(STRUCTURE);
  assert.throws(() => xbfPoseValues(kinematics, { elbw: 1 }), /names no joint 'elbw'/);
  assert.throws(() => xbfPoseValues(kinematics, { elbow: 150 }), /'elbow' at 150 deg is outside its range \[-10, 120\]/);
  assert.throws(() => xbfPoseValues(kinematics, "folded"), /no configuration 'folded'/);
  assert.throws(() => xbfPoseValues({ ...kinematics, loop: ["elbow", "b"] }, { elbow: 0 }),
    /joint 'elbow' cannot be posed: pairs elbow, b close a loop/);
  assert.deepEqual(xbfPoseControls(kinematics), [{ id: "elbow", pair: "elbow", index: 0, label: "elbow", unit: "deg", min: -10, max: 120 }]);
});

test("a structure the engine served posed is posed from where it stands", () => {
  // The engine's posed structure: the arm's matrix at 90, and `kinematics.pose` saying so.
  const kinematics = xbfKinematics(STRUCTURE);
  const raised = xbfPosedMatrices(STRUCTURE, { elbow: [90] });
  const posed = { ...STRUCTURE, instances: STRUCTURE.instances.map((instance, at) => ({ ...instance, matrix: raised[at] })),
    kinematics: { ...kinematics, pose: { values: { elbow: 90 }, configuration: "raised" } } };
  near(place(xbfPosedMatrices(posed, { elbow: [0] })[ARM], [120, 10, 10]), armTip(0), "from the served pose");
});

// The finger's knuckles in its pairs' order, and its joints' values in that order.
const KNUCKLES = ["index_mcp_flexion", "index_pip", "index_dip"];
const knuckles = (...values) => Object.fromEntries(KNUCKLES.map((label, at) => [label, [values[at]]]));

test("a coupling poses its joints as the engine does: at its value, the joints set by hand", () => {
  const kinematics = xbfKinematics(FINGER);
  assert.deepEqual(kinematics.couplings.index_curl.terms, [[KNUCKLES[0], 0, 90], [KNUCKLES[1], 0, 100], [KNUCKLES[2], 0, 70]]);
  const coupled = xbfPoseValues(kinematics, { index_curl: 0.6 });
  // By hand: the same finger with no coupling, whose joints are its own to set.
  const byHand = xbfPoseValues({ ...kinematics, couplings: {} }, { index_mcp_flexion: 54, index_pip: 60, index_dip: 42 });
  for (const label of KNUCKLES) near(coupled[label], byHand[label], label);
  // The page's forward kinematics at the coupling is the engine's, instance by instance.
  xbfPosedMatrices(FINGER, coupled).forEach((matrix, at) => near(matrix, FINGER_POSED.matrices[at], `instance ${at}`));
  xbfPosedMatrices(FINGER, byHand).forEach((matrix, at) => near(matrix, FINGER_POSED.matrices[at], `by hand, instance ${at}`));
  // What a coupling pose names wrong is refused by name, as the engine refuses it.
  assert.throws(() => xbfPoseValues(kinematics, { index_curl: 1.5 }), /coupling 'index_curl' at 1.5 is outside its range \[0, 1\]/);
  assert.throws(() => xbfPoseValues(kinematics, { index_curl: 0.5, index_pip: 10 }),
    /joint 'index_pip' moves only with its coupling 'index_curl'; set 'index_curl'/);
  assert.throws(() => xbfPoseValues(kinematics, { index_curl: "x" }), /coupling 'index_curl' takes a number/);
  assert.throws(() => xbfPoseValues(kinematics, { crul: 1 }), /names no joint 'crul'/);
  // The panel: one control for the coupling over its derived range, and none for its joints.
  assert.deepEqual(xbfCouplingControls(kinematics), [{ id: "coupling:index_curl", coupling: "index_curl", label: "index_curl", unit: "",
    min: 0, max: 1, pairs: KNUCKLES }]);
});

test("a coupling is its joints' only way to move, and a pose's place on a coupling is read back", () => {
  const kinematics = xbfKinematics(FINGER);
  assert.deepEqual(xbfPoseControls(kinematics), [], "no slider of a coupling's joints");
  assert.throws(() => xbfPoseValues(kinematics, { index_pip: 10 }),
    /joint 'index_pip' moves only with its coupling 'index_curl'; set 'index_curl'/);
  assert.deepEqual(xbfPoseValues(kinematics, { index_curl: 0.5 }), knuckles(45, 50, 35));
  // Where a pose stands on it: its value on its line, 0 off it.
  assert.deepEqual(xbfCouplingValues(kinematics, knuckles(45, 50, 35)), { index_curl: 0.5 });
  assert.deepEqual(xbfCouplingValues(kinematics, knuckles(45, 0, 35)), { index_curl: 0 });
  // A coupling joint that cannot be posed (it closes a loop) takes its coupling with it, said by name.
  const stuck = { ...kinematics, loop: ["index_dip", "x"] };
  assert.equal(xbfUnposable(stuck).get("index_curl"), "its joint 'index_dip' cannot be");
  assert.deepEqual(xbfCouplingControls(stuck), []);
});

test("a coupling's write holds its joints within their limits, and couplings sharing a joint add", () => {
  const hinge = xbfKinematics(STRUCTURE);
  // `swing`'s range is open on both sides: its joint's limits alone hold it.
  const kinematics = { ...hinge, couplings: {
    swing: { range: [null, null], terms: [["elbow", 0, 90]] },
    nudge: { range: [-1, 1], terms: [["elbow", 0, 10]] } } };
  // An open side spans one turn of its first value from the other; both open, half a turn each way.
  assert.deepEqual(xbfCouplingControls(kinematics).map(({ coupling, min, max }) => [coupling, min, max]),
    [["swing", -2, 2], ["nudge", -1, 1]]);
  assert.deepEqual(xbfCouplingControls({ ...kinematics, couplings: { swing: { range: [null, 1], terms: [["elbow", 0, 90]] } } })
    .map(({ min, max }) => [min, max]), [[-3, 1]]);
  const asBuilt = xbfPoseValues(kinematics);
  // Elbow is 30 as built and stops at 120: swing stops at 1 however far it is dragged.
  assert.deepEqual(xbfCouplingWrite(kinematics, asBuilt, {}, "swing", 2), { values: { elbow: [120] }, couplings: { swing: 1 } });
  assert.equal(xbfCouplingWrite(kinematics, asBuilt, {}, "swing", Number.NaN), null);
  // A second coupling adds its share: the engine's pose of both, and the panel's writes of each.
  const written = xbfCouplingWrite(kinematics, asBuilt, { swing: 0.5 }, "nudge", 1);
  assert.deepEqual(written, { values: { elbow: [85] }, couplings: { swing: 0.5, nudge: 1 } });
  assert.deepEqual(xbfPoseValues(kinematics, { swing: 0.5, nudge: 1 }), { elbow: [85] });
  near(place(xbfPosedMatrices(STRUCTURE, written.values)[ARM], [120, 10, 10]), armTip(85), "both couplings");
  assert.throws(() => xbfPoseValues(kinematics, { swing: 1, nudge: 1 }), /couplings 'swing' at 1, 'nudge' at 1: joint 'elbow' at 130 deg is outside its range \[-10, 120\]/);
});

test("the scene moves an instance's group to the pose, and its element's matrix with it", () => {
  const parts = new Map(STRUCTURE.prototypes.map((prototype) => {
    const file = fs.readFileSync(path.join(FIXTURE, `${prototype.key}.xbm`));
    const mesh = readXbmPart(file.buffer.slice(file.byteOffset, file.byteOffset + file.byteLength));
    const held = new Map();
    return [prototype.key, { key: prototype.key, mesh, unmeshed: xbmUnmeshedFaces(mesh), retain() { return this; }, release() {},
      hold(name, make) { if (!held.has(name)) held.set(name, make()); return held.get(name); } }];
  }));
  const scene = createXbfScene(THREE, { structure: STRUCTURE, parts, version: "1-1" });
  assert.ok(scene.kinematics);
  scene.setPose({ elbow: [90] });
  const group = scene.object3D.children[ARM].children[0];
  near(place(group.matrixWorld.elements, [120, 10, 10]), armTip(90), "the arm's group");
  near(place(scene.describeElement("i1/face/1").matrix, [120, 10, 10]), armTip(90), "the element's matrix");
  assert.deepEqual(scene.object3D.children[0].children[0].matrix.elements, STRUCTURE.instances[0].matrix);
  scene.setPose(null);
  assert.deepEqual(scene.describeElement("i1/face/1").matrix, STRUCTURE.instances[ARM].matrix);
  scene.dispose();
});
